		s.Join(joinT).On(s.C(tag.FieldID), joinT.C(material.TagsPrimaryKey[1]))
		s.Where(sql.InValues(joinT.C(material.TagsPrimaryKey[0]), edgeIDs...))
		columns := s.SelectedColumns()
